begin;
create table if not exists public.payment_tenders(
 id bigint generated by default as identity primary key,
 payment_id bigint not null references public.payments(id) on delete cascade,
 clinic_id bigint not null default public.current_clinic_id() references public.clinics(id),
 method text not null check(method in('cash','bank_transfer','card','online','tabby','tamara','other')),
 amount numeric(14,2) not null check(amount>0),reference_number text,created_at timestamptz not null default now()
);
alter table public.payment_tenders enable row level security;
drop policy if exists payment_tenders_scope on public.payment_tenders;
create policy payment_tenders_scope on public.payment_tenders for all to authenticated using(clinic_id=public.current_clinic_id()) with check(clinic_id=public.current_clinic_id());
grant select,insert,update,delete on public.payment_tenders to authenticated;grant usage,select on all sequences in schema public to authenticated;
create or replace function public.payment_tender_scope()returns trigger language plpgsql security definer set search_path=public as $$declare invoice_total numeric;other_total numeric;begin select clinic_id,amount into new.clinic_id,invoice_total from payments where id=new.payment_id;if new.clinic_id is null then raise exception 'Invoice not found';end if;select coalesce(sum(amount),0) into other_total from payment_tenders where payment_id=new.payment_id and id is distinct from new.id;if other_total+new.amount>invoice_total then raise exception 'Split payment exceeds invoice total';end if;return new;end$$;
drop trigger if exists payment_tender_scope_trigger on public.payment_tenders;create trigger payment_tender_scope_trigger before insert or update on public.payment_tenders for each row execute function public.payment_tender_scope();

create or replace function public.accounting_payment_post()returns trigger language plpgsql security definer set search_path=public as $$
declare j jsonb:=to_jsonb(new);eid bigint;receipt_id bigint;ar_id bigint;revenue_id bigint;vat_id bigint;discount_id bigint;doctor_id bigint;t record;allocated numeric:=0;method text:=lower(coalesce(j->>'payment_method','cash'));status text:=lower(coalesce(j->>'payment_status','pending'));invoice_ref text:=coalesce(nullif(j->>'invoice_number',''),'#'||new.id::text);paid numeric:=coalesce(nullif(j->>'paid_amount','')::numeric,nullif(j->>'amount','')::numeric,0);subtotal numeric:=coalesce(nullif(j->>'subtotal_amount','')::numeric,greatest(coalesce(nullif(j->>'amount','')::numeric,0)-coalesce(nullif(j->>'tax_amount','')::numeric,0),0));tax numeric:=coalesce(nullif(j->>'tax_amount','')::numeric,0);discount numeric:=coalesce(nullif(j->>'discount_amount','')::numeric,0);total numeric;balance numeric;
begin
 select a.doctor_id into doctor_id from appointments a where a.id=new.appointment_id and a.clinic_id=new.clinic_id;delete from accounting_journal_entries where clinic_id=new.clinic_id and source_type='payment' and source_id=new.id;if status in('cancelled','canceled')then return new;end if;total:=greatest(subtotal-discount+tax,0);balance:=greatest(total-paid,0);if total=0 then return new;end if;
 ar_id:=accounting_account_id(new.clinic_id,'accounts_receivable');revenue_id:=accounting_account_id(new.clinic_id,'service_revenue');vat_id:=accounting_account_id(new.clinic_id,'vat_payable');discount_id:=accounting_account_id(new.clinic_id,'sales_discounts');insert into accounting_journal_entries(clinic_id,branch_id,entry_number,entry_date,description_en,description_ar,status,source_type,source_id)values(new.clinic_id,new.branch_id,'PAY-'||new.id,coalesce(nullif(j->>'payment_date','')::timestamptz::date,current_date),'Patient invoice '||invoice_ref,'فاتورة مريض '||invoice_ref,'draft','payment',new.id)returning id into eid;
 for t in select method,amount from payment_tenders where payment_id=new.id loop receipt_id:=accounting_account_id(new.clinic_id,case when t.method='cash'then'cash'when t.method='bank_transfer'then'bank'else'gateway_clearing'end);insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,staff_id,debit,credit,memo_en,memo_ar)values(eid,new.clinic_id,receipt_id,new.customer_id,doctor_id,t.amount,0,t.method,t.method);allocated:=allocated+t.amount;end loop;
 if allocated=0 and paid>0 then receipt_id:=accounting_account_id(new.clinic_id,case when method in('cash','نقدا','نقداً')then'cash'when method in('bank','bank_transfer','transfer','تحويل بنكي')then'bank'else'gateway_clearing'end);insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,staff_id,debit,credit)values(eid,new.clinic_id,receipt_id,new.customer_id,doctor_id,least(paid,total),0);allocated:=least(paid,total);end if;
 balance:=greatest(total-allocated,0);if balance>0 then insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,staff_id,debit,credit)values(eid,new.clinic_id,ar_id,new.customer_id,doctor_id,balance,0);end if;if discount>0 then insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,staff_id,debit,credit)values(eid,new.clinic_id,discount_id,new.customer_id,doctor_id,discount,0);end if;if subtotal>0 then insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,staff_id,debit,credit)values(eid,new.clinic_id,revenue_id,new.customer_id,doctor_id,0,subtotal);end if;if tax>0 then insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,staff_id,debit,credit)values(eid,new.clinic_id,vat_id,new.customer_id,doctor_id,0,tax);end if;update accounting_journal_entries set status='posted',posted_at=now()where id=eid;return new;end$$;
commit;
